    s.background = { color: PRIMARY };

    // Top header band in accent
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.9,
      fill: { color: ACCENT }, line: { color: ACCENT }
    });
    s.addText("[SLIDE 5 TITLE: THE TAKEAWAY]", {
