      x: 0.4, y: 0, w: 9.2, h: 0.9,
      fontSize: 13, color: PRIMARY,
      align: "right", valign: "middle", margin: 0
    });

    // Main takeaway (prominent)
    s.addText("[ONE CLEAR ACTIONABLE TAKEAWAY]", {
      x: 0.5, y: 1.2, w: 9, h: 1.2,
      fontSize: 24, fontFace: "Calibri", color: WHITE, bold: true,
      align: "center", valign: "middle", margin: 0
