// build.js - turn one reviews/<folder>/review.json into the week's outputs.
//
//   node tools/build.js reviews/001_sleep-extension
//
// Writes to build/<folder>/:
//   RI5-001_<slug>.pptx   5-slide deck (publish.ps1 turns it into the PDF)
//   teams.md             Teams channel post
//   email.txt            Subject line + plain-text body for Outlook
//
// Validation runs first. Length limits exist because pptxgenjs does not shrink
// text to fit: a long bullet silently overflows its box. Fix the words, not
// the limits.

const fs = require("fs");
const path = require("path");
const pptxgen = require("pptxgenjs");

// Analytic theme: one light background, hairline rules, Agency FB throughout.
// Colors follow Baylor_Doc_Style: green for type and rules, dark gold for the one
// highlighted value per slide (bright Baylor gold is unreadable as text on white).
// Agency FB has no italic face, so hierarchy comes from size, weight, and color.
// No tracked all-caps labels, cards, accent bars, or header/footer strips.
const FONT = "Agency FB";
const BG = "FCFCFA";
const GREEN = "154734";
const GOLD = "B8860B";
const INK = "1F2A24";
const GREY = "595959";
const RULE = "C9D1CC";
const EMPTY = "E6EAE7"; // unfilled evidence-scale steps

const LEVELS = ["Preliminary", "Moderate", "Strong"]; // weakest to strongest

// ---------------------------------------------------------------- validation

function validate(r) {
  const errors = [];
  const warnings = [];
  const need = (cond, msg) => { if (!cond) errors.push(msg); };
  const maxLen = (s, n, where) => {
    if (typeof s !== "string" || !s.trim()) errors.push(`${where}: missing`);
    else if (s.length > n) errors.push(`${where}: ${s.length} chars, limit ${n}: "${s.slice(0, 50)}..."`);
  };
  const list = (arr, min, max, where) => {
    if (!Array.isArray(arr)) { errors.push(`${where}: missing list`); return []; }
    if (arr.length < min || arr.length > max) errors.push(`${where}: ${arr.length} items, need ${min}-${max}`);
    return arr;
  };

  need(Number.isInteger(r.number) && r.number >= 0, "number: integer >= 0 required");
  need(/^\d{4}-\d{2}-\d{2}$/.test(r.date || ""), "date: YYYY-MM-DD required");
  need(/^[a-z0-9-]+$/.test(r.slug || ""), "slug: lowercase kebab-case required");
  maxLen(r.topic, 32, "topic");

  const p = r.paper || {};
  maxLen(p.title, 170, "paper.title");
  maxLen(p.authors, 40, "paper.authors");
  maxLen(p.journal, 60, "paper.journal");
  need(Number.isInteger(p.year), "paper.year: integer required");
  if (!p.doi && !p.url) errors.push("paper: doi or url required");
  if (p.full_text === false) warnings.push("paper.full_text is false: review built from abstract only; say so in the post");

  maxLen(r.hook, 150, "hook");

  const t = r.trust || {};
  need(LEVELS.includes(t.level), `trust.level: one of ${LEVELS.join(", ")}`);
  maxLen(t.design, 45, "trust.design");
  maxLen(t.sample, 60, "trust.sample");
  list(t.limitations, 1, 3, "trust.limitations").forEach((s, i) => {
    maxLen(s, 70, `trust.limitations[${i}]`);
    if (/;/.test(s)) errors.push(`trust.limitations[${i}]: no semicolons; limitations are joined with "; "`);
  });

  const d = r.did || {};
  maxLen(d.question, 170, "did.question");
  list(d.facts, 2, 3, "did.facts").forEach((f, i) => {
    maxLen(f.label, 14, `did.facts[${i}].label`);
    maxLen(f.value, 40, `did.facts[${i}].value`);
  });
  list(d.bullets, 2, 4, "did.bullets").forEach((s, i) => maxLen(s, 115, `did.bullets[${i}]`));

  const res = r.results || {};
  list(res.stats, 1, 3, "results.stats").forEach((s, i) => {
    maxLen(s.value, 8, `results.stats[${i}].value`);
    maxLen(s.label, 70, `results.stats[${i}].label`);
    if (s.page === undefined) warnings.push(`results.stats[${i}]: no page number; every number should trace to the paper`);
  });
  list(res.bullets, 1, 3, "results.bullets").forEach((s, i) => maxLen(s, 140, `results.bullets[${i}]`));
  if (res.table !== undefined) {
    const tb = res.table;
    const cols = list(tb.columns, 3, 5, "results.table.columns");
    cols.forEach((c, i) => maxLen(c, 22, `results.table.columns[${i}]`));
    list(tb.rows, 1, 8, "results.table.rows").forEach((row, i) => {
      if (!Array.isArray(row) || row.length !== cols.length) errors.push(`results.table.rows[${i}]: needs ${cols.length} cells`);
      else row.forEach((c, j) => maxLen(String(c), 22, `results.table.rows[${i}][${j}]`));
    });
    maxLen(tb.source, 60, "results.table.source");
  } else {
    warnings.push("results.table missing: slide 3 shows key numbers only; add the paper's main table when it has one");
  }

  const m = r.meaning || {};
  maxLen(m.summary, 200, "meaning.summary");
  list(m.roles, 2, 4, "meaning.roles").forEach((x, i) => {
    maxLen(x.role, 28, `meaning.roles[${i}].role`);
    maxLen(x.line, 125, `meaning.roles[${i}].line`);
  });

  const k = r.takeaways || {};
  list(k.bullets, 2, 3, "takeaways.bullets").forEach((s, i) => maxLen(s, 110, `takeaways.bullets[${i}]`));
  maxLen(k.question, 150, "takeaways.question");

  // Writing rule from AGENTS.md: no em or en dashes anywhere.
  const raw = JSON.stringify(r);
  if (/[\u2013\u2014]/.test(raw)) errors.push("text contains an em or en dash; use a comma, colon, or new sentence");

  return { errors, warnings };
}

// ---------------------------------------------------------------- deck

function pad(n) { return String(n).padStart(3, "0"); }

function buildDeck(r, outFile) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9"; // 10 x 5.625 in
  pres.author = "Baylor Athletics Applied Performance";
  pres.title = `Research in 5 #${pad(r.number)}: ${r.paper.title}`;

  const X = 0.6;   // left margin
  const W = 8.8;   // content width
  const T = { fontFace: FONT, margin: 0 };

  const slide = () => {
    const s = pres.addSlide();
    s.background = { color: BG };
    return s;
  };
  const rule = (s, x, y, w, color = RULE, width = 0.75) =>
    s.addShape(pres.shapes.LINE, { x, y, w, h: 0, line: { color, width } });

  // Section slides: "01" in gold, question as the title, green rule under it.
  const section = (idx, title) => {
    const s = slide();
    s.addText(idx, { ...T, x: X, y: 0.38, w: 0.6, h: 0.7, fontSize: 30, bold: true, color: GOLD, valign: "bottom" });
    s.addText(title, { ...T, x: X + 0.62, y: 0.38, w: W - 0.62, h: 0.7, fontSize: 38, bold: true, color: GREEN, valign: "bottom" });
    rule(s, X, 1.18, W, GREEN, 1.25);
    return s;
  };

  // 1. The paper
  {
    const s = slide();
    s.addText(`Research in 5  ·  #${pad(r.number)}  ·  ${r.topic}`, { ...T, x: X, y: 0.4, w: W, h: 0.35, fontSize: 16, color: GREY });
    const len = r.paper.title.length;
    const size = len > 120 ? 34 : len > 80 ? 38 : 44;
    s.addText(r.paper.title, { ...T, x: X, y: 0.85, w: W, h: 1.95, fontSize: size, bold: true, color: GREEN, valign: "top" });
    const abstractNote = r.paper.full_text === false ? "  ·  Summary based on the abstract" : "";
    s.addText(`${r.paper.authors} (${r.paper.year})  ·  ${r.paper.journal}  ·  ${link(r)}${abstractNote}`, { ...T, x: X, y: 2.9, w: W, h: 0.35, fontSize: 15, color: GREY });
    rule(s, X, 3.45, W, GREEN, 1.25);

    s.addText(r.hook, { ...T, x: X, y: 3.7, w: 5.3, h: 1.3, fontSize: 22, color: INK, valign: "top" });

    // Evidence scale: three steps, filled up to the rated level.
    const sx = 6.35, sw = 3.05, gap = 0.06, step = (sw - gap * 2) / 3;
    const filled = LEVELS.indexOf(r.trust.level);
    s.addText("Evidence", { ...T, x: sx, y: 3.62, w: sw, h: 0.3, fontSize: 15, bold: true, color: GREEN });
    LEVELS.forEach((lv, i) => {
      const x = sx + i * (step + gap);
      const on = i <= filled;
      s.addShape(pres.shapes.RECTANGLE, { x, y: 3.97, w: step, h: 0.16, fill: { color: on ? GREEN : EMPTY }, line: { color: on ? GREEN : EMPTY, width: 0 } });
      s.addText(lv, { ...T, x, y: 4.17, w: step, h: 0.28, fontSize: 13, bold: i === filled, color: i === filled ? GREEN : GREY });
    });
    s.addText(`${r.trust.design}\n${r.trust.sample}`, { ...T, x: sx, y: 4.52, w: sw, h: 0.6, fontSize: 14, color: GREY, valign: "top" });
  }

  // 2. What did the researchers do?
  {
    const s = section("01", "What did the researchers do?");
    s.addText(r.did.question, { ...T, x: X, y: 1.35, w: W, h: 0.8, fontSize: 22, color: INK, valign: "top" });

    const top = 2.3, bottom = 5.15, lw = 5.25;
    const rowH = (bottom - top) / r.did.bullets.length;
    r.did.bullets.forEach((b, i) => {
      const y = top + i * rowH;
      rule(s, X, y, lw);
      s.addText(String(i + 1), { ...T, x: X, y: y + 0.08, w: 0.35, h: rowH - 0.12, fontSize: 18, bold: true, color: GOLD, valign: "top" });
      s.addText(b, { ...T, x: X + 0.38, y: y + 0.08, w: lw - 0.38, h: rowH - 0.12, fontSize: 17, color: INK, valign: "top" });
    });

    // Spec sheet: label over value, hairline between.
    const sx = 6.25, sw = 3.15;
    const slot = (bottom - top) / r.did.facts.length;
    r.did.facts.forEach((f, i) => {
      const y = top + i * slot;
      rule(s, sx, y, sw);
      s.addText(f.label, { ...T, x: sx, y: y + 0.08, w: sw, h: 0.28, fontSize: 14, color: GREY });
      s.addText(f.value, { ...T, x: sx, y: y + 0.36, w: sw, h: slot - 0.44, fontSize: 20, bold: true, color: GREEN, valign: "top" });
    });
  }

  // 3. What were the results?
  {
    const s = section("02", "What were the results?");
    const tb = r.results.table;
    const top = 1.4;

    // Key numbers: left column when there is a table, a row across when not.
    const stats = r.results.stats;
    const pageLabel = (pg) => (typeof pg === "number" ? `p. ${pg}` : String(pg));
    if (tb) {
      const lw = 2.7, slot = 3.75 / stats.length;
      stats.forEach((st, i) => {
        const y = top + i * slot;
        if (i > 0) rule(s, X, y - 0.05, lw);
        s.addText(st.value, { ...T, x: X, y, w: lw, h: 0.7, fontSize: 44, bold: true, color: i === 0 ? GOLD : GREEN, valign: "top" });
        const note = st.page !== undefined ? ` (${pageLabel(st.page)})` : "";
        s.addText(st.label + note, { ...T, x: X, y: y + 0.68, w: lw, h: slot - 0.78, fontSize: 14, color: GREY, valign: "top" });
      });

      const tx = 3.65, tw = X + W - tx;
      const ncol = tb.columns.length;
      const firstW = tw * (ncol > 3 ? 0.34 : 0.44);
      const restW = (tw - firstW) / (ncol - 1);
      const colW = [firstW, ...Array(ncol - 1).fill(restW)];
      const cell = (text, o = {}) => ({ text: String(text), options: { fontFace: FONT, fontSize: 14, color: INK, margin: [0.02, 0.04, 0.02, 0.04], valign: "middle", border: [{ type: "none" }, { type: "none" }, { pt: 0.75, color: RULE }, { type: "none" }], ...o } });
      const header = tb.columns.map((c, j) => cell(c, { bold: true, color: GREEN, align: j === 0 ? "left" : "right", border: [{ type: "none" }, { type: "none" }, { pt: 1.25, color: GREEN }, { type: "none" }] }));
      const body = tb.rows.map((row) => row.map((c, j) => cell(c, { align: j === 0 ? "left" : "right" })));
      const rowH = Math.min(0.32, 2.75 / (tb.rows.length + 1));
      s.addTable([header, ...body], { x: tx, y: top, w: tw, colW, rowH });
      const tableBottom = top + rowH * (tb.rows.length + 1);
      s.addText(tb.source, { ...T, x: tx, y: tableBottom + 0.04, w: tw, h: 0.25, fontSize: 12, color: GREY });

      const by = tableBottom + 0.38;
      s.addText(r.results.bullets.map((b, i) => ({ text: b, options: { bullet: { indent: 12 }, paraSpaceAfter: 3, breakLine: i < r.results.bullets.length - 1 } })),
        { ...T, x: tx, y: by, w: tw, h: 5.2 - by, fontSize: 14, color: INK, valign: "top" });
    } else {
      const gap = 0.3, w = (W - gap * (stats.length - 1)) / stats.length;
      stats.forEach((st, i) => {
        const x = X + i * (w + gap);
        s.addText(st.value, { ...T, x, y: top, w, h: 0.85, fontSize: 54, bold: true, color: i === 0 ? GOLD : GREEN, valign: "top" });
        const note = st.page !== undefined ? ` (${pageLabel(st.page)})` : "";
        s.addText(st.label + note, { ...T, x, y: top + 0.85, w, h: 0.6, fontSize: 15, color: GREY, valign: "top" });
      });
      rule(s, X, 3.0, W);
      s.addText(r.results.bullets.map((b, i) => ({ text: b, options: { bullet: { indent: 14 }, paraSpaceAfter: 6, breakLine: i < r.results.bullets.length - 1 } })),
        { ...T, x: X, y: 3.15, w: W, h: 2.0, fontSize: 18, color: INK, valign: "top" });
    }
  }

  // 4. What does this mean?
  {
    const s = section("03", "What does this mean?");
    s.addText(r.meaning.summary, { ...T, x: X, y: 1.35, w: W, h: 0.8, fontSize: 22, color: INK, valign: "top" });

    const roles = r.meaning.roles;
    const rows = Math.ceil(roles.length / 2);
    const top = 2.3, area = 1.95, colW = 4.2, colGap = W - colW * 2;
    const h = area / rows;
    roles.forEach((ro, i) => {
      const x = X + (i % 2) * (colW + colGap);
      const y = top + Math.floor(i / 2) * h;
      rule(s, x, y, colW);
      s.addText(ro.role, { ...T, x, y: y + 0.06, w: colW, h: 0.3, fontSize: 16, bold: true, color: GREEN });
      s.addText(ro.line, { ...T, x, y: y + 0.36, w: colW, h: h - 0.42, fontSize: 16, color: INK, valign: "top" });
    });

    rule(s, X, 4.4, W, GREEN, 1.25);
    s.addText([
      { text: `How much to trust it: ${r.trust.level}`, options: { bold: true, color: GREEN, fontSize: 17, breakLine: true } },
      { text: `${r.trust.design}, ${r.trust.sample}. Limits: ${limits(r)}.`, options: { color: INK, fontSize: 15 } },
    ], { ...T, x: X, y: 4.5, w: W, h: 0.72, valign: "top" });
  }

  // 5. Coaching takeaways
  {
    const s = section("04", "Coaching takeaways");
    const top = 1.35, rowH = 0.72;
    r.takeaways.bullets.forEach((t, i) => {
      const y = top + i * rowH;
      if (i > 0) rule(s, X, y, W);
      s.addText(String(i + 1), { ...T, x: X, y: y + 0.04, w: 0.45, h: rowH - 0.08, fontSize: 30, bold: true, color: GOLD, valign: "middle" });
      s.addText(t, { ...T, x: X + 0.5, y: y + 0.04, w: W - 0.5, h: rowH - 0.08, fontSize: 21, color: INK, valign: "middle" });
    });

    const dy = top + rowH * 3 + 0.2;
    rule(s, X, dy, W, GREEN, 1.25);
    s.addText("For discussion", { ...T, x: X, y: dy + 0.1, w: W, h: 0.32, fontSize: 17, bold: true, color: GREEN });
    s.addText(r.takeaways.question, { ...T, x: X, y: dy + 0.42, w: W, h: 0.7, fontSize: 21, color: INK, valign: "top" });
    s.addText(citation(r), { ...T, x: X, y: 5.02, w: W, h: 0.4, fontSize: 11, color: GREY, valign: "top" });
  }

  return pres.writeFile({ fileName: outFile });
}

// ---------------------------------------------------------------- text posts

function link(r) { return r.paper.doi ? `https://doi.org/${r.paper.doi}` : r.paper.url; }

function citation(r) {
  const p = r.paper;
  return `${p.authors} (${p.year}). ${p.title}. ${p.journal}. ${link(r)}`;
}

// "Small sample; no control group" reads better than "Small sample; No control group".
function limits(r) {
  return r.trust.limitations.map((s, i) => (i === 0 ? s : s.charAt(0).toLowerCase() + s.slice(1))).join("; ");
}

function trustLine(r) {
  const t = r.trust;
  return `${t.level}. ${t.design}, ${t.sample}. Limits: ${limits(r)}.`;
}

function teamsPost(r) {
  const L = [];
  L.push(`**Research in 5 · #${pad(r.number)}: ${r.paper.title}**`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("_Built from the abstract; full text was not available._", "");
  L.push("**What did the researchers do?**", r.did.question);
  r.did.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What were the results?**");
  r.results.stats.forEach((s) => L.push(`- **${s.value}** ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What does this mean?**", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`- **${x.role}:** ${x.line}`));
  L.push("", "**Coaching takeaways**");
  r.takeaways.bullets.forEach((b, i) => L.push(`${i + 1}. ${b}`));
  L.push("", `**How much to trust it:** ${trustLine(r)}`);
  L.push("", `**Discuss:** ${r.takeaways.question}`);
  L.push("", citation(r), "The 5-slide deck is attached.");
  return L.join("\n") + "\n";
}

function email(r) {
  const L = [];
  L.push(`Subject: Research in 5 #${pad(r.number)}: ${r.topic}`, "");
  L.push("Hi all,", "");
  L.push(`This week's paper: ${r.paper.title} (${r.paper.authors}, ${r.paper.journal}, ${r.paper.year}).`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("Note: built from the abstract; full text was not available.", "");
  L.push("WHAT DID THE RESEARCHERS DO?", r.did.question);
  r.did.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT WERE THE RESULTS?");
  r.results.stats.forEach((s) => L.push(`  • ${s.value}: ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT DOES THIS MEAN?", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`  • ${x.role}: ${x.line}`));
  L.push("", "COACHING TAKEAWAYS");
  r.takeaways.bullets.forEach((b, i) => L.push(`  ${i + 1}. ${b}`));
  L.push("", `HOW MUCH TO TRUST IT: ${trustLine(r)}`);
  L.push("", `Something to think about: ${r.takeaways.question}`);
  L.push("", "The 5-slide deck is attached as a PDF.", "", `Full paper: ${link(r)}`, "");
  return L.join("\n");
}

// ---------------------------------------------------------------- main

async function main() {
  const dir = process.argv[2];
  if (!dir) { console.error("usage: node tools/build.js reviews/<folder>"); process.exit(2); }
  const file = path.join(dir, "review.json");
  const r = JSON.parse(fs.readFileSync(file, "utf8"));

  const { errors, warnings } = validate(r);
  warnings.forEach((w) => console.log(`WARN  ${w}`));
  if (errors.length) {
    errors.forEach((e) => console.log(`ERROR ${e}`));
    console.log(`\n${errors.length} error(s). Fix review.json and rerun.`);
    process.exit(1);
  }

  const folder = path.basename(path.resolve(dir));
  const out = path.join(__dirname, "..", "build", folder);
  fs.mkdirSync(out, { recursive: true });
  const base = `RI5-${pad(r.number)}_${r.slug}`;
  await buildDeck(r, path.join(out, `${base}.pptx`));
  fs.writeFileSync(path.join(out, "teams.md"), teamsPost(r));
  fs.writeFileSync(path.join(out, "email.txt"), email(r));
  console.log(`OK    ${path.resolve(out)}`);
  console.log(`      ${base}.pptx, teams.md, email.txt`);
}

if (require.main === module) main().catch((e) => { console.error(e); process.exit(1); });

module.exports = { validate, citation };

toolUseResult.content:
// build.js - turn one reviews/<folder>/review.json into the week's outputs.
//
//   node tools/build.js reviews/001_sleep-extension
//
// Writes to build/<folder>/:
//   RI5-001_<slug>.pptx   5-slide deck (publish.ps1 turns it into the PDF)
//   teams.md             Teams channel post
//   email.txt            Subject line + plain-text body for Outlook
//
// Validation runs first. Length limits exist because pptxgenjs does not shrink
// text to fit: a long bullet silently overflows its box. Fix the words, not
// the limits.

const fs = require("fs");
const path = require("path");
const pptxgen = require("pptxgenjs");

// Analytic theme: one light background, hairline rules, Agency FB throughout.
// Colors follow Baylor_Doc_Style: green for type and rules, dark gold for the one
// highlighted value per slide (bright Baylor gold is unreadable as text on white).
// Agency FB has no italic face, so hierarchy comes from size, weight, and color.
// No tracked all-caps labels, cards, accent bars, or header/footer strips.
const FONT = "Agency FB";
const BG = "FCFCFA";
const GREEN = "154734";
const GOLD = "B8860B";
const INK = "1F2A24";
const GREY = "595959";
const RULE = "C9D1CC";
const EMPTY = "E6EAE7"; // unfilled evidence-scale steps

const LEVELS = ["Preliminary", "Moderate", "Strong"]; // weakest to strongest

// ---------------------------------------------------------------- validation

function validate(r) {
  const errors = [];
  const warnings = [];
  const need = (cond, msg) => { if (!cond) errors.push(msg); };
  const maxLen = (s, n, where) => {
    if (typeof s !== "string" || !s.trim()) errors.push(`${where}: missing`);
    else if (s.length > n) errors.push(`${where}: ${s.length} chars, limit ${n}: "${s.slice(0, 50)}..."`);
  };
  const list = (arr, min, max, where) => {
    if (!Array.isArray(arr)) { errors.push(`${where}: missing list`); return []; }
    if (arr.length < min || arr.length > max) errors.push(`${where}: ${arr.length} items, need ${min}-${max}`);
    return arr;
  };

  need(Number.isInteger(r.number) && r.number >= 0, "number: integer >= 0 required");
  need(/^\d{4}-\d{2}-\d{2}$/.test(r.date || ""), "date: YYYY-MM-DD required");
  need(/^[a-z0-9-]+$/.test(r.slug || ""), "slug: lowercase kebab-case required");
  maxLen(r.topic, 32, "topic");

  const p = r.paper || {};
  maxLen(p.title, 170, "paper.title");
  maxLen(p.authors, 40, "paper.authors");
  maxLen(p.journal, 60, "paper.journal");
  need(Number.isInteger(p.year), "paper.year: integer required");
  if (!p.doi && !p.url) errors.push("paper: doi or url required");
  if (p.full_text === false) warnings.push("paper.full_text is false: review built from abstract only; say so in the post");

  maxLen(r.hook, 150, "hook");

  const t = r.trust || {};
  need(LEVELS.includes(t.level), `trust.level: one of ${LEVELS.join(", ")}`);
  maxLen(t.design, 45, "trust.design");
  maxLen(t.sample, 60, "trust.sample");
  list(t.limitations, 1, 3, "trust.limitations").forEach((s, i) => {
    maxLen(s, 70, `trust.limitations[${i}]`);
    if (/;/.test(s)) errors.push(`trust.limitations[${i}]: no semicolons; limitations are joined with "; "`);
  });

  const d = r.did || {};
  maxLen(d.question, 170, "did.question");
  list(d.facts, 2, 3, "did.facts").forEach((f, i) => {
    maxLen(f.label, 14, `did.facts[${i}].label`);
    maxLen(f.value, 40, `did.facts[${i}].value`);
  });
  list(d.bullets, 2, 4, "did.bullets").forEach((s, i) => maxLen(s, 115, `did.bullets[${i}]`));

  const res = r.results || {};
  list(res.stats, 1, 3, "results.stats").forEach((s, i) => {
    maxLen(s.value, 8, `results.stats[${i}].value`);
    maxLen(s.label, 70, `results.stats[${i}].label`);
    if (s.page === undefined) warnings.push(`results.stats[${i}]: no page number; every number should trace to the paper`);
  });
  list(res.bullets, 1, 3, "results.bullets").forEach((s, i) => maxLen(s, 140, `results.bullets[${i}]`));
  if (res.table !== undefined) {
    const tb = res.table;
    const cols = list(tb.columns, 3, 5, "results.table.columns");
    cols.forEach((c, i) => maxLen(c, 22, `results.table.columns[${i}]`));
    list(tb.rows, 1, 8, "results.table.rows").forEach((row, i) => {
      if (!Array.isArray(row) || row.length !== cols.length) errors.push(`results.table.rows[${i}]: needs ${cols.length} cells`);
      else row.forEach((c, j) => maxLen(String(c), 22, `results.table.rows[${i}][${j}]`));
    });
    maxLen(tb.source, 60, "results.table.source");
  } else {
    warnings.push("results.table missing: slide 3 shows key numbers only; add the paper's main table when it has one");
  }

  const m = r.meaning || {};
  maxLen(m.summary, 200, "meaning.summary");
  list(m.roles, 2, 4, "meaning.roles").forEach((x, i) => {
    maxLen(x.role, 28, `meaning.roles[${i}].role`);
    maxLen(x.line, 125, `meaning.roles[${i}].line`);
  });

  const k = r.takeaways || {};
  list(k.bullets, 2, 3, "takeaways.bullets").forEach((s, i) => maxLen(s, 110, `takeaways.bullets[${i}]`));
  maxLen(k.question, 150, "takeaways.question");

  // Writing rule from AGENTS.md: no em or en dashes anywhere.
  const raw = JSON.stringify(r);
  if (/[–—]/.test(raw)) errors.push("text contains an em or en dash; use a comma, colon, or new sentence");

  return { errors, warnings };
}

// ---------------------------------------------------------------- deck

function pad(n) { return String(n).padStart(3, "0"); }

function buildDeck(r, outFile) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9"; // 10 x 5.625 in
  pres.author = "Baylor Athletics Applied Performance";
  pres.title = `Research in 5 #${pad(r.number)}: ${r.paper.title}`;

  const X = 0.6;   // left margin
  const W = 8.8;   // content width
  const T = { fontFace: FONT, margin: 0 };

  const slide = () => {
    const s = pres.addSlide();
    s.background = { color: BG };
    return s;
  };
  const rule = (s, x, y, w, color = RULE, width = 0.75) =>
    s.addShape(pres.shapes.LINE, { x, y, w, h: 0, line: { color, width } });

  // Section slides: "01" in gold, question as the title, green rule under it.
  const section = (idx, title) => {
    const s = slide();
    s.addText(idx, { ...T, x: X, y: 0.38, w: 0.6, h: 0.7, fontSize: 30, bold: true, color: GOLD, valign: "bottom" });
    s.addText(title, { ...T, x: X + 0.62, y: 0.38, w: W - 0.62, h: 0.7, fontSize: 38, bold: true, color: GREEN, valign: "bottom" });
    rule(s, X, 1.18, W, GREEN, 1.25);
    return s;
  };

  // 1. The paper
  {
    const s = slide();
    s.addText(`Research in 5  ·  #${pad(r.number)}  ·  ${r.topic}`, { ...T, x: X, y: 0.4, w: W, h: 0.35, fontSize: 16, color: GREY });
    const len = r.paper.title.length;
    const size = len > 120 ? 34 : len > 80 ? 38 : 44;
    s.addText(r.paper.title, { ...T, x: X, y: 0.85, w: W, h: 1.95, fontSize: size, bold: true, color: GREEN, valign: "top" });
    const abstractNote = r.paper.full_text === false ? "  ·  Summary based on the abstract" : "";
    s.addText(`${r.paper.authors} (${r.paper.year})  ·  ${r.paper.journal}  ·  ${link(r)}${abstractNote}`, { ...T, x: X, y: 2.9, w: W, h: 0.35, fontSize: 15, color: GREY });
    rule(s, X, 3.45, W, GREEN, 1.25);

    s.addText(r.hook, { ...T, x: X, y: 3.7, w: 5.3, h: 1.3, fontSize: 22, color: INK, valign: "top" });

    // Evidence scale: three steps, filled up to the rated level.
    const sx = 6.35, sw = 3.05, gap = 0.06, step = (sw - gap * 2) / 3;
    const filled = LEVELS.indexOf(r.trust.level);
    s.addText("Evidence", { ...T, x: sx, y: 3.62, w: sw, h: 0.3, fontSize: 15, bold: true, color: GREEN });
    LEVELS.forEach((lv, i) => {
      const x = sx + i * (step + gap);
      const on = i <= filled;
      s.addShape(pres.shapes.RECTANGLE, { x, y: 3.97, w: step, h: 0.16, fill: { color: on ? GREEN : EMPTY }, line: { color: on ? GREEN : EMPTY, width: 0 } });
      s.addText(lv, { ...T, x, y: 4.17, w: step, h: 0.28, fontSize: 13, bold: i === filled, color: i === filled ? GREEN : GREY });
    });
    s.addText(`${r.trust.design}\n${r.trust.sample}`, { ...T, x: sx, y: 4.52, w: sw, h: 0.6, fontSize: 14, color: GREY, valign: "top" });
  }

  // 2. What did the researchers do?
  {
    const s = section("01", "What did the researchers do?");
    s.addText(r.did.question, { ...T, x: X, y: 1.35, w: W, h: 0.8, fontSize: 22, color: INK, valign: "top" });

    const top = 2.3, bottom = 5.15, lw = 5.25;
    const rowH = (bottom - top) / r.did.bullets.length;
    r.did.bullets.forEach((b, i) => {
      const y = top + i * rowH;
      rule(s, X, y, lw);
      s.addText(String(i + 1), { ...T, x: X, y: y + 0.08, w: 0.35, h: rowH - 0.12, fontSize: 18, bold: true, color: GOLD, valign: "top" });
      s.addText(b, { ...T, x: X + 0.38, y: y + 0.08, w: lw - 0.38, h: rowH - 0.12, fontSize: 17, color: INK, valign: "top" });
    });

    // Spec sheet: label over value, hairline between.
    const sx = 6.25, sw = 3.15;
    const slot = (bottom - top) / r.did.facts.length;
    r.did.facts.forEach((f, i) => {
      const y = top + i * slot;
      rule(s, sx, y, sw);
      s.addText(f.label, { ...T, x: sx, y: y + 0.08, w: sw, h: 0.28, fontSize: 14, color: GREY });
      s.addText(f.value, { ...T, x: sx, y: y + 0.36, w: sw, h: slot - 0.44, fontSize: 20, bold: true, color: GREEN, valign: "top" });
    });
  }

  // 3. What were the results?
  {
    const s = section("02", "What were the results?");
    const tb = r.results.table;
    const top = 1.4;

    // Key numbers: left column when there is a table, a row across when not.
    const stats = r.results.stats;
    const pageLabel = (pg) => (typeof pg === "number" ? `p. ${pg}` : String(pg));
    if (tb) {
      const lw = 2.7, slot = 3.75 / stats.length;
      stats.forEach((st, i) => {
        const y = top + i * slot;
        if (i > 0) rule(s, X, y - 0.05, lw);
        s.addText(st.value, { ...T, x: X, y, w: lw, h: 0.7, fontSize: 44, bold: true, color: i === 0 ? GOLD : GREEN, valign: "top" });
        const note = st.page !== undefined ? ` (${pageLabel(st.page)})` : "";
        s.addText(st.label + note, { ...T, x: X, y: y + 0.68, w: lw, h: slot - 0.78, fontSize: 14, color: GREY, valign: "top" });
      });

      const tx = 3.65, tw = X + W - tx;
      const ncol = tb.columns.length;
      const firstW = tw * (ncol > 3 ? 0.34 : 0.44);
      const restW = (tw - firstW) / (ncol - 1);
      const colW = [firstW, ...Array(ncol - 1).fill(restW)];
      const cell = (text, o = {}) => ({ text: String(text), options: { fontFace: FONT, fontSize: 14, color: INK, margin: [0.02, 0.04, 0.02, 0.04], valign: "middle", border: [{ type: "none" }, { type: "none" }, { pt: 0.75, color: RULE }, { type: "none" }], ...o } });
      const header = tb.columns.map((c, j) => cell(c, { bold: true, color: GREEN, align: j === 0 ? "left" : "right", border: [{ type: "none" }, { type: "none" }, { pt: 1.25, color: GREEN }, { type: "none" }] }));
      const body = tb.rows.map((row) => row.map((c, j) => cell(c, { align: j === 0 ? "left" : "right" })));
      const rowH = Math.min(0.32, 2.75 / (tb.rows.length + 1));
      s.addTable([header, ...body], { x: tx, y: top, w: tw, colW, rowH });
      const tableBottom = top + rowH * (tb.rows.length + 1);
      s.addText(tb.source, { ...T, x: tx, y: tableBottom + 0.04, w: tw, h: 0.25, fontSize: 12, color: GREY });

      const by = tableBottom + 0.38;
      s.addText(r.results.bullets.map((b, i) => ({ text: b, options: { bullet: { indent: 12 }, paraSpaceAfter: 3, breakLine: i < r.results.bullets.length - 1 } })),
        { ...T, x: tx, y: by, w: tw, h: 5.2 - by, fontSize: 14, color: INK, valign: "top" });
    } else {
      const gap = 0.3, w = (W - gap * (stats.length - 1)) / stats.length;
      stats.forEach((st, i) => {
        const x = X + i * (w + gap);
        s.addText(st.value, { ...T, x, y: top, w, h: 0.85, fontSize: 54, bold: true, color: i === 0 ? GOLD : GREEN, valign: "top" });
        const note = st.page !== undefined ? ` (${pageLabel(st.page)})` : "";
        s.addText(st.label + note, { ...T, x, y: top + 0.85, w, h: 0.6, fontSize: 15, color: GREY, valign: "top" });
      });
      rule(s, X, 3.0, W);
      s.addText(r.results.bullets.map((b, i) => ({ text: b, options: { bullet: { indent: 14 }, paraSpaceAfter: 6, breakLine: i < r.results.bullets.length - 1 } })),
        { ...T, x: X, y: 3.15, w: W, h: 2.0, fontSize: 18, color: INK, valign: "top" });
    }
  }

  // 4. What does this mean?
  {
    const s = section("03", "What does this mean?");
    s.addText(r.meaning.summary, { ...T, x: X, y: 1.35, w: W, h: 0.8, fontSize: 22, color: INK, valign: "top" });

    const roles = r.meaning.roles;
    const rows = Math.ceil(roles.length / 2);
    const top = 2.3, area = 1.95, colW = 4.2, colGap = W - colW * 2;
    const h = area / rows;
    roles.forEach((ro, i) => {
      const x = X + (i % 2) * (colW + colGap);
      const y = top + Math.floor(i / 2) * h;
      rule(s, x, y, colW);
      s.addText(ro.role, { ...T, x, y: y + 0.06, w: colW, h: 0.3, fontSize: 16, bold: true, color: GREEN });
      s.addText(ro.line, { ...T, x, y: y + 0.36, w: colW, h: h - 0.42, fontSize: 16, color: INK, valign: "top" });
    });

    rule(s, X, 4.4, W, GREEN, 1.25);
    s.addText([
      { text: `How much to trust it: ${r.trust.level}`, options: { bold: true, color: GREEN, fontSize: 17, breakLine: true } },
      { text: `${r.trust.design}, ${r.trust.sample}. Limits: ${limits(r)}.`, options: { color: INK, fontSize: 15 } },
    ], { ...T, x: X, y: 4.5, w: W, h: 0.72, valign: "top" });
  }

  // 5. Coaching takeaways
  {
    const s = section("04", "Coaching takeaways");
    const top = 1.35, rowH = 0.72;
    r.takeaways.bullets.forEach((t, i) => {
      const y = top + i * rowH;
      if (i > 0) rule(s, X, y, W);
      s.addText(String(i + 1), { ...T, x: X, y: y + 0.04, w: 0.45, h: rowH - 0.08, fontSize: 30, bold: true, color: GOLD, valign: "middle" });
      s.addText(t, { ...T, x: X + 0.5, y: y + 0.04, w: W - 0.5, h: rowH - 0.08, fontSize: 21, color: INK, valign: "middle" });
    });

    const dy = top + rowH * 3 + 0.2;
    rule(s, X, dy, W, GREEN, 1.25);
    s.addText("For discussion", { ...T, x: X, y: dy + 0.1, w: W, h: 0.32, fontSize: 17, bold: true, color: GREEN });
    s.addText(r.takeaways.question, { ...T, x: X, y: dy + 0.42, w: W, h: 0.7, fontSize: 21, color: INK, valign: "top" });
    s.addText(citation(r), { ...T, x: X, y: 5.02, w: W, h: 0.4, fontSize: 11, color: GREY, valign: "top" });
  }

  return pres.writeFile({ fileName: outFile });
}

// ---------------------------------------------------------------- text posts

function link(r) { return r.paper.doi ? `https://doi.org/${r.paper.doi}` : r.paper.url; }

function citation(r) {
  const p = r.paper;
  return `${p.authors} (${p.year}). ${p.title}. ${p.journal}. ${link(r)}`;
}

// "Small sample; no control group" reads better than "Small sample; No control group".
function limits(r) {
  return r.trust.limitations.map((s, i) => (i === 0 ? s : s.charAt(0).toLowerCase() + s.slice(1))).join("; ");
}

function trustLine(r) {
  const t = r.trust;
  return `${t.level}. ${t.design}, ${t.sample}. Limits: ${limits(r)}.`;
}

function teamsPost(r) {
  const L = [];
  L.push(`**Research in 5 · #${pad(r.number)}: ${r.paper.title}**`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("_Built from the abstract; full text was not available._", "");
  L.push("**What did the researchers do?**", r.did.question);
  r.did.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What were the results?**");
  r.results.stats.forEach((s) => L.push(`- **${s.value}** ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`- ${b}`));
  L.push("", "**What does this mean?**", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`- **${x.role}:** ${x.line}`));
  L.push("", "**Coaching takeaways**");
  r.takeaways.bullets.forEach((b, i) => L.push(`${i + 1}. ${b}`));
  L.push("", `**How much to trust it:** ${trustLine(r)}`);
  L.push("", `**Discuss:** ${r.takeaways.question}`);
  L.push("", citation(r), "The 5-slide deck is attached.");
  return L.join("\n") + "\n";
}

function email(r) {
  const L = [];
  L.push(`Subject: Research in 5 #${pad(r.number)}: ${r.topic}`, "");
  L.push("Hi all,", "");
  L.push(`This week's paper: ${r.paper.title} (${r.paper.authors}, ${r.paper.journal}, ${r.paper.year}).`);
  L.push(r.hook, "");
  if (r.paper.full_text === false) L.push("Note: built from the abstract; full text was not available.", "");
  L.push("WHAT DID THE RESEARCHERS DO?", r.did.question);
  r.did.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT WERE THE RESULTS?");
  r.results.stats.forEach((s) => L.push(`  • ${s.value}: ${s.label}`));
  r.results.bullets.forEach((b) => L.push(`  • ${b}`));
  L.push("", "WHAT DOES THIS MEAN?", r.meaning.summary);
  r.meaning.roles.forEach((x) => L.push(`  • ${x.role}: ${x.line}`));
  L.push("", "COACHING TAKEAWAYS");
  r.takeaways.bullets.forEach((b, i) => L.push(`  ${i + 1}. ${b}`));
  L.push("", `HOW MUCH TO TRUST IT: ${trustLine(r)}`);
  L.push("", `Something to think about: ${r.takeaways.question}`);
  L.push("", "The 5-slide deck is attached as a PDF.", "", `Full paper: ${link(r)}`, "");
  return L.join("\n");
}

// ---------------------------------------------------------------- main

async function main() {
  const dir = process.argv[2];
  if (!dir) { console.error("usage: node tools/build.js reviews/<folder>"); process.exit(2); }
  const file = path.join(dir, "review.json");
  const r = JSON.parse(fs.readFileSync(file, "utf8"));

  const { errors, warnings } = validate(r);
  warnings.forEach((w) => console.log(`WARN  ${w}`));
  if (errors.length) {
    errors.forEach((e) => console.log(`ERROR ${e}`));
    console.log(`\n${errors.length} error(s). Fix review.json and rerun.`);
    process.exit(1);
  }

  const folder = path.basename(path.resolve(dir));
  const out = path.join(__dirname, "..", "build", folder);
  fs.mkdirSync(out, { recursive: true });
  const base = `RI5-${pad(r.number)}_${r.slug}`;
  await buildDeck(r, path.join(out, `${base}.pptx`));
  fs.writeFileSync(path.join(out, "teams.md"), teamsPost(r));
  fs.writeFileSync(path.join(out, "email.txt"), email(r));
  console.log(`OK    ${path.resolve(out)}`);
  console.log(`      ${base}.pptx, teams.md, email.txt`);
}

if (require.main === module) main().catch((e) => { console.error(e); process.exit(1); });

module.exports = { validate, citation };

