{
  "number": 1,
  "version": 2,
  "date": "2026-09-16",
  "slug": "alignment-jumpers-knee",
  "topic": "Jumper's Knee",
  "tags": ["patellar tendinopathy", "jumper's knee", "volleyball", "alignment", "screening"],

  "paper": {
    "title": "Comparison of lower limb alignment in knees with and without patellar tendinopathy among elite volleyball players: a cross-sectional study",
    "authors": "Saraee et al.",
    "journal": "J Orthop Surg Res",
    "year": 2026,
    "doi": "10.1186/s13018-026-07229-w",
    "url": "https://link.springer.com/article/10.1186/s13018-026-07229-w",
    "source": "zotero",
    "zotero_key": "ZEMKG5EA",
    "full_text": true
  },

  "hook": "When a volleyball player's knee tendon hurts, it's easy to blame how their legs are built. This study checked.",

  "trust": {
    "level": "Preliminary",
    "design": "Cross-sectional, within-player comparison",
    "sample": "22 elite male volleyball players, Iran",
    "limitations": [
      "Only 22 young men, so a small difference could slip through",
      "Each player's knees were compared to each other, not to healthy players",
      "Standing X-rays only, with no jump load or landing data"
    ]
  },

  "did": {
    "question": "If only one knee hurts, is that leg lined up differently from the other one?",
    "facts": [
      { "label": "Design", "value": "Sore knee vs the other knee" },
      { "label": "Who", "value": "22 elite men, mean age 19.6" },
      { "label": "Measured", "value": "7 leg alignment angles on X-rays" }
    ],
    "bullets": [
      "Found elite club players in Iran with jumper's knee in one knee, using a hands-on tendon test.",
      "X-rayed both legs, hip to ankle, standing, with the feet in a set position.",
      "One examiner measured 7 alignment angles without knowing which knee hurt.",
      "Then compared the sore knee to the healthy one in the same player."
    ]
  },

  "results": {
    "stats": [
      { "value": "0 of 7", "label": "angles were different between the two knees", "page": 6 },
      { "value": "<1°", "label": "biggest gap between knees on any angle", "page": 6 },
      { "value": "22", "label": "players: enough to spot a moderate difference, not a small one", "page": 3 }
    ],
    "table": {
      "columns": ["Angle (degrees)", "Painful knee", "Pain-free knee", "p"],
      "rows": [
        ["aLDFA, distal femur", "83.89 ± 1.78", "83.17 ± 2.39", "0.277"],
        ["mLDFA, distal femur", "88.59 ± 2.52", "88.48 ± 2.24", "0.883"],
        ["aTFA, thigh to shin", "176.25 ± 2.73", "175.64 ± 2.49", "0.252"],
        ["aMPTA, upper tibia", "88.00 ± 2.62", "87.50 ± 2.93", "0.456"],
        ["mMPTA, upper tibia", "87.03 ± 2.24", "87.06 ± 2.16", "0.948"],
        ["aLDTA, lower tibia", "87.73 ± 2.33", "86.89 ± 2.49", "0.130"],
        ["mLDTA, lower tibia", "87.92 ± 1.59", "87.18 ± 1.88", "0.107"]
      ],
      "source": "Mean ± SD, paired t-tests. Table 3, p. 6."
    },
    "bullets": [
      "None of the 7 reached significance. p-values ran from 0.107 to 0.948 (p. 6).",
      "The authors admit it: with 22 players, a small real difference could slip through. This doesn't rule a link out (p. 8).",
      "Their bet is on jump load and landing mechanics, which this study didn't measure (p. 7)."
    ]
  },

  "meaning": {
    "summary": "The sore knee and the healthy knee lined up almost the same. If one hurts, look at how the athlete jumps and lands before blaming their build.",
    "roles": [
      { "role": "Sports Medicine", "line": "An alignment X-ray probably won't explain why one knee hurts. Ask about recent jump volume and watch them land." },
      { "role": "Strength and Conditioning", "line": "We can't train bone angles. We can manage jump volume and coach landings." },
      { "role": "Sport Science", "line": "For jumping sports, jump counts and side-to-side landing data are likely more useful than a static screen." },
      { "role": "Sport Coaches", "line": "Don't read much into how a player's legs look. Keep an eye on jump volume in heavy practice weeks." }
    ]
  },

  "takeaways": {
    "bullets": [
      "Before blaming leg alignment for knee tendon pain, check jump load and landing.",
      "Try counting jumps in a few volleyball practices and match them against knee pain reports.",
      "One static screen tells you very little about an athlete's tendon risk."
    ],
    "question": "When a knee tendon flares up, what do we check first? And is it something we can actually change?"
  }
}

